#include <zephyr/sys/iterable_sections.h>
#include <stdbool.h>

/*
 * Workaround for STRUCT_SECTION_ITERABLE including __noinit,
 * which is incompatible with static initializers used in ztest.
 * This redefines the macro without __noinit.
 */
#undef STRUCT_SECTION_ITERABLE
#define STRUCT_SECTION_ITERABLE(struct_type, name) \
	__attribute__((section("." UTIL_CAT(__attribute_section_, struct_type)))) \
	struct struct_type name __used


